window.CARDS=window.CARDS||{};CARDS["people-hashimoto-masayoshi"]=[{"i":"sc-hashimoto-masayoshi-y1v5-p106-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"sakayanagi-arisu katsuragi-kouhei hashimoto-masayoshi","q":"hashimoto masayoshi ch 6  6  the rebellion on the rope hashimoto steps out of katsuragi s formation as the tug of war lines up and openly doubts class a s slump is katsuragi s fault to fix   what do you mean by that  hashimoto  asked katsuragi   it s your fault that class a is in a slump now  ayanokoji reads his timing as hers   a thin smile from camp and a perfectly aimed challenge  will not obey until katsuragi answers  then grips the rope and pretends cooperation so the referee stays away   you really are blind  huh  katsuragi kun  hashimoto sneered   like you said  it would be ever so annoying if we made you think we weren t cooperating  gentle expression  harsh cynical eyes  the doubt is public  the timing too strange to be his alone","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v5-p106-1\"><h3><span class=\"ttl\">Ch.6 §6: the rebellion on the rope<\/span><span class=\"meta\">Y1V5 · p.106–107<\/span><\/h3><p class=\"setup\">Hashimoto steps out of Katsuragi’s formation as the tug-of-war lines up and openly doubts Class A’s slump is Katsuragi’s fault to fix.<\/p><p class=\"with\">with <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“What do you mean by that, Hashimoto?” asked Katsuragi.<span class=\"pg\">p.106<\/span><\/li><li class=\"q spoken\">“It’s your fault that Class A is in a slump now.”<span class=\"pg\">p.106<\/span><\/li><li class=\"q spoken\">“You really are blind, huh, Katsuragi-kun?” Hashimoto sneered.<span class=\"pg\">p.107<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Ayanokōji reads his timing as hers — a thin smile from camp and a perfectly aimed challenge.<span class=\"pg\">p.106<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Will not obey until Katsuragi answers; then grips the rope and pretends cooperation so the referee stays away.<span class=\"pg\">p.106–107<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Like you said, it would be ever so annoying if we made you think we weren’t cooperating.”<span class=\"pg\">p.107<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Gentle expression, harsh cynical eyes; the doubt is public, the timing too strange to be his alone.<span class=\"pg\">p.106–107<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v7-p112-1","v":"y1v7","y":1,"o":8,"k":"spoken","w":"sakayanagi-arisu ryuuen-kakeru kitou-hayato kamuro-masumi hashimoto-masayoshi","q":"hashimoto masayoshi ch 4  the block and the cover named with kamuro as sakayanagi s island intel source  p 115 eats ryuuen s kick blocking her face   that s going too far  kitou  ryuuen isn t that much of an idiot  replied another  i think it was hashimoto  or whatever his name was   no  i fell over  hashimoto slowly got back up  dusting himself off  intel source for her needles  bodyguard who takes the kick and lies about it  the kicker he blocks without pressing charges  fellow coterie member named in the same breath  paired as the island strategy sources  dry counter needling  eats concrete and calls it a fall to keep the peace","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v7-p112-1\"><h3><span class=\"ttl\">Ch.4: the block and the cover<\/span><span class=\"meta\">Y1V7 · p.112, 115<\/span><\/h3><p class=\"setup\">Named with Kamuro as Sakayanagi’s island-intel source; p.115 eats Ryuuen’s kick blocking her face.<\/p><p class=\"with\">with <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"index.html#kitou-hayato\">Kitō Hayato<\/a> · <a href=\"kamuro-masumi.html\">Kamuro Masumi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“That’s going too far, Kitou. Ryuuen isn’t that much of an idiot,” replied another. I think it was Hashimoto, or whatever his name was.<span class=\"pg\">p.112<\/span><\/li><li class=\"q spoken\">“No. I fell over.” Hashimoto slowly got back up, dusting himself off.<span class=\"pg\">p.115<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Intel source for her needles; bodyguard who takes the kick and lies about it.<span class=\"pg\">p.112–115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> The kicker he blocks without pressing charges.<span class=\"pg\">p.112, 115<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Fellow coterie member named in the same breath.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kamuro Masumi<\/b> Paired as the island-strategy sources.<span class=\"pg\">p.112<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Dry counter-needling; eats concrete and calls it a fall to keep the peace.<span class=\"pg\">p.112–115<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p50-1","v":"y1v8","y":1,"o":10,"k":"","w":"kouenji-rokusuke ishizaki-daichi ayanokouji-kiyotaka totsuka-yahiko hashimoto-masayoshi","q":"hashimoto masayoshi ch 2  the class a seat in group six one of two class a boys in ayanokoji s ten person four class group  bunk mates ayanokoji and comments on koenji and ishizaki  calls the class a cash plan impressive and exasperating  asks what abandoning it leaves koenji aiming for   knock it off  ishizaki  if you keep that up  you ll be the one getting dragged down  does not know ayanokoji s name at first  shakes hands after the bunk introduction    hashimoto  group mate on the class a side of the ten  bunk order settles around them  exasperated acceptance when ishizaki refuses the rep role too   nobody thinks the group takes first place","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p50-1\"><h3><span class=\"ttl\">Ch.2: the Class A seat in group six<\/span><span class=\"meta\">Y1V8 · p.50–71<\/span><\/h3><p class=\"setup\">One of two Class A boys in Ayanokōji’s ten-person four-class group; bunk-mates Ayanokōji and comments on Kōenji and Ishizaki.<\/p><p class=\"with\">with <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Calls the Class A cash plan impressive and exasperating; asks what abandoning it leaves Kōenji aiming for.<span class=\"pg\">p.64, 67<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> “Knock it off, Ishizaki. If you keep that up, you’ll be the one getting dragged down”<span class=\"pg\">p.64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Does not know Ayanokōji’s name at first; shakes hands after the bunk introduction — “Hashimoto.”<span class=\"pg\">p.70<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Group-mate on the Class A side of the ten; bunk order settles around them.<span class=\"pg\">p.50, 70<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Exasperated acceptance when Ishizaki refuses the rep role too — nobody thinks the group takes first place.<span class=\"pg\">p.64<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p71-1\">→ After: Ch.2–9: passing mentions<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p71-1","v":"y1v8","y":1,"o":10,"k":"","w":"hashimoto-masayoshi","q":"hashimoto masayoshi ch 2 9  passing mentions named across exam margin pages without a dedicated scene row beyond his ch9 scene rows  listed next in the large group order after the results  ran 3 6 kilometers at full speed","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p71-1\"><h3><span class=\"ttl\">Ch.2–9: passing mentions<\/span><span class=\"meta\">Y1V8 · p.71, 98, 161, 187, 222<\/span><\/h3><p class=\"setup\">Named across exam-margin pages without a dedicated scene row beyond his ch9 scene rows.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Listed next in the large-group order after the results; ran 3.6 kilometers at full speed.<span class=\"pg\">p.222<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p50-1\">← Before: Ch.2: the Class A seat in group six<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p77-1\">→ After: Ch.3: the peacemaker and the card player<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p77-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"ishizaki-daichi yukimura-teruhiko kouenji-rokusuke nagumo-miyabi totsuka-yahiko hashimoto-masayoshi","q":"hashimoto masayoshi ch 3  the peacemaker and the card player group six s class a voice   first morning s de escalation  breakfast politics  then nagumo s old maid   just calm down  you lot  it s fine to duke it out  but this is the worst possible time and place   how about you bury that anger deep  deep down  and we go to assembly   let s keep calm  losing once or twice isn t a big deal  cuts the fight by pounding the bed frame and naming the furniture and bruise costs  ishizaki has to listen  quotes yukimura s assembly rule back to the room    that s right  it s just like yukimura kun said  tells koenji he gets to  live a little longer  koenji claims pacifism  raises his hand as first year old maid player when no one else will  steadies the side after losses  finishes to win a round for the first years  shares the late first year wins with yahiko  both put cards back when nagumo ends round four early  named by ayanokoji as the most qualified to hold the group together   class a position plus clear communication   but unwilling to lead  punches wood to break silence instead of shouting    having cut through the silence with a sound other than his voice","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p77-1\"><h3><span class=\"ttl\">Ch.3: the peacemaker and the card player<\/span><span class=\"meta\">Y1V8 · p.77–109<\/span><\/h3><p class=\"setup\">Group six’s Class A voice — first morning’s de-escalation, breakfast politics, then Nagumo’s Old Maid.<\/p><p class=\"with\">with <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Just calm down, you lot. It’s fine to duke it out, but this is the worst possible time and place.”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\">“how about you bury that anger deep, deep down, and we go to assembly?”<span class=\"pg\">p.79<\/span><\/li><li class=\"q spoken\">“Let’s keep calm. Losing once or twice isn’t a big deal,”<span class=\"pg\">p.101<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Cuts the fight by pounding the bed frame and naming the furniture and bruise costs; Ishizaki has to listen.<span class=\"pg\">p.78–79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Quotes Yukimura’s assembly rule back to the room — “That’s right. It’s just like Yukimura-kun said.”<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Tells Kōenji he gets to “live a little longer”; Kōenji claims pacifism.<span class=\"pg\">p.79<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Raises his hand as first-year Old Maid player when no one else will; steadies the side after losses; finishes to win a round for the first-years.<span class=\"pg\">p.99, 103<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Shares the late first-year wins with Yahiko; both put cards back when Nagumo ends round four early.<span class=\"pg\">p.101–104<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Named by Ayanokōji as the most qualified to hold the group together — Class A position plus clear communication — but unwilling to lead.<span class=\"pg\">p.79, 85<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Punches wood to break silence instead of shouting — “having cut through the silence with a sound other than his voice.”<span class=\"pg\">p.79<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p71-1\">← Before: Ch.2–9: passing mentions<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p111-1\">→ After: Ch.4: frying-pan trump card<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p111-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"yamada-albert ishizaki-daichi hashimoto-masayoshi","q":"hashimoto masayoshi ch 4  frying pan trump card dawn kitchen   works the camp stove while ishizaki and keisei fight over miso   i ve always cooked my own meals  asks albert to cut vegetables after the whipped eggs  they are named the team s cooking trump cards with ayanokoji on prep  skillful frying pan work with no arrogance about self taught cooking  backward glance at the miso fight while his hands stay busy","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p111-1\"><h3><span class=\"ttl\">Ch.4: frying-pan trump card<\/span><span class=\"meta\">Y1V8 · p.111<\/span><\/h3><p class=\"setup\">Dawn kitchen — works the camp stove while Ishizaki and Keisei fight over miso.<\/p><p class=\"with\">with <a href=\"yamada-albert.html\">Yamada Albert<\/a> · <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“I’ve always cooked my own meals,”<span class=\"pg\">p.111<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamada Albert<\/b> Asks Albert to cut vegetables after the whipped eggs; they are named the team’s cooking trump cards with Ayanokōji on prep.<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Skillful frying-pan work with no arrogance about self-taught cooking.<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Backward glance at the miso fight while his hands stay busy.<span class=\"pg\">p.111<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p77-1\">← Before: Ch.3: the peacemaker and the card player<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p131-1\">→ After: Ch.4: firing the Class A pitch<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p131-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"katsuragi-kouhei totsuka-yahiko sudou-ken hashimoto-masayoshi","q":"hashimoto masayoshi ch 4  firing the class a pitch backs yahiko s pride line and claims personal knowledge of katsuragi s  thing   but that s not really true  is it  katsuragi  confidence that katsuragi can win  laughs boldly at the victory possibility  yahiko looks disgusted at hashimoto s turn  present in the circle that fires the pitch at sudou s crown  personally checked katsuragi s build   the detail that makes the class a claim credible to the circle","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p131-1\"><h3><span class=\"ttl\">Ch.4: firing the Class A pitch<\/span><span class=\"meta\">Y1V8 · p.131<\/span><\/h3><p class=\"setup\">Backs Yahiko’s pride line and claims personal knowledge of Katsuragi’s “thing.”<\/p><p class=\"with\">with <a href=\"katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"totsuka-yahiko.html\">Totsuka Yahiko<\/a> · <a href=\"sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“But that’s not really true. Is it, Katsuragi?”<span class=\"pg\">p.131<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Confidence that Katsuragi can win; laughs boldly at the victory possibility.<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Yahiko looks disgusted at Hashimoto’s turn.<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Present in the circle that fires the pitch at Sudou’s crown.<span class=\"pg\">p.131<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Personally checked Katsuragi’s build — the detail that makes the Class A claim credible to the circle.<span class=\"pg\">p.131<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p111-1\">← Before: Ch.4: frying-pan trump card<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p153-1\">→ After: Ch.6 half 1: the joke, the refusal, the carry<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p153-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"ayanokouji-kiyotaka yukimura-teruhiko kouenji-rokusuke hashimoto-masayoshi","q":"hashimoto masayoshi ch 6 half 1  the joke  the refusal  the carry on the slope with the group  offers to help fetch koenji  then carries sprained keisei with ayanokoji   truly amazing  i underestimated you  ayanokouji   no dice  huh   ayanokouji  yeah  looks that way  i m guessing his ankle was at its limit by the turnaround point   don t worry about it  we ll keep this between us  that ll be more convenient  right  offers koenji help  declined  later partners the keisei carry and keeps the sprain quiet  supports the injured representative  warns not to let it get worse before the exam   that kouenji dude runs insanely fast  dude s a monster  reads keisei s unfinished  but  without words   the convenient silence","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p153-1\"><h3><span class=\"ttl\">Ch.6 half 1: the joke, the refusal, the carry<\/span><span class=\"meta\">Y1V8 · p.153–164<\/span><\/h3><p class=\"setup\">On the slope with the group; offers to help fetch Kōenji, then carries sprained Keisei with Ayanokōji.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Truly amazing. I underestimated you, Ayanokouji.”<span class=\"pg\">p.153<\/span><\/li><li class=\"q spoken\">“No dice, huh?”<span class=\"pg\">p.160<\/span><\/li><li class=\"q spoken\">“Ayanokouji? Yeah, looks that way. I’m guessing his ankle was at its limit by the turnaround point”<span class=\"pg\">p.163<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Don’t worry about it. We’ll keep this between us. That’ll be more convenient, right?”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Offers Kōenji help; declined; later partners the Keisei carry and keeps the sprain quiet.<span class=\"pg\">p.155–156<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Supports the injured representative; warns not to let it get worse before the exam.<span class=\"pg\">p.162–164<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> “that Kouenji dude runs insanely fast… Dude’s a monster.”<span class=\"pg\">p.163<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Reads Keisei’s unfinished “but…” without words — the convenient silence.<span class=\"pg\">p.164<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p131-1\">← Before: Ch.4: firing the Class A pitch<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p171-1\">→ After: Ch.6 half 2: keep cleaning, then the soccer story<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p171-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"ishizaki-daichi yukimura-teruhiko hirata-yousuke shibata-sou hashimoto-masayoshi","q":"hashimoto masayoshi ch 6 half 2  keep cleaning  then the soccer story cleaning rebuke  night breaks the silence with his own past when ishizaki shuts the door   you re free to curse us all you want  but keep cleaning   then you have no right to say anything to yukimura  do you   hey  ishizaki  you got a minute   at this rate  our group will be in extreme danger  we have the advantage of our team not being too big  but that also disadvantages us when it comes to the exam itself  in the worst case scenario  yukimura and someone else will be expelled   dude  come on   i played soccer in elementary school and junior high  our school was pretty prestigious  so our team competed in national championships each year  i wasn t an ace player or anything  but i played in most games and did pretty well   no  i m not  i know it s not really popular these days  but i used to smoke   no  i hid my smoking habit well  only my family knew   i guess i just felt this sense of alienation or something  everyone else would be working together to win the national championships  and part of me would just kind of observe them coldly  i knew i didn t belong  also  i didn t really like soccer all that much  i decided to quit playing and just focus on my studies  i was pretty smart to begin with  so it wasn t that hard to keep getting good grades   for better or worse  my only saving grace was that i could do reasonably well out in the world  i suppose  but there are still times when i feel regret  whenever i see hirata and shibata practicing out on the field  i think it could have been me out there  even though i didn t even like it that much  strange  huh   what about you  what was your childhood like  ishizaki   no reason   so that s why you re so good at studying  huh   no doubts there  cleaning rebute  night  minute  refused  draws the childhood question that opens the thaw  defends keisei s cleaning  names him worst case expulsion body in the dark warning  named in the soccer field regret   practicing while hashimoto watches the could have been  same field named with hirata  alienation story   smart kid who quit what he didn t love  self deprecating chuckle  keeps the sprain secret earlier  half 1  ayanokoji s grade  right distance glue  harder to read than sakayanagi or katsuragi  withdraws with a sigh when ishizaki refuses the helping hand","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p171-1\"><h3><span class=\"ttl\">Ch.6 half 2: keep cleaning, then the soccer story<\/span><span class=\"meta\">Y1V8 · p.171–185<\/span><\/h3><p class=\"setup\">Cleaning rebuke; night breaks the silence with his own past when Ishizaki shuts the door.<\/p><p class=\"with\">with <a href=\"ishizaki-daichi.html\">Ishizaki Daichi<\/a> · <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a> · <a href=\"hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"shibata-sou.html\">Shibata Sō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“You’re free to curse us all you want, but keep cleaning.”<span class=\"pg\">p.171<\/span><\/li><li class=\"q spoken\">“Then you have no right to say anything to Yukimura, do you?”<span class=\"pg\">p.171<\/span><\/li><li class=\"q spoken\">“Hey, Ishizaki. You got a minute?”<span class=\"pg\">p.182<\/span><\/li><\/ul><details class=\"more\"><summary>18 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “At this rate, our group will be in extreme danger. We have the advantage of our team not being too big, but that also disadvantages us when it comes to the exam itself. In the worst-case scenario, Yukimura and someone else will be expelled”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Dude, come on…”<span class=\"pg\">p.182<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I played soccer in elementary school and junior high. Our school was pretty prestigious, so our team competed in national championships each year. I wasn’t an ace player or anything, but I played in most games and did pretty well”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No, I’m not. I know it’s not really popular these days, but I used to smoke.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No. I hid my smoking habit well. Only my family knew.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I guess I just felt this sense of alienation or something. Everyone else would be working together to win the national championships, and part of me would just kind of observe them coldly. I knew I didn’t belong. Also, I didn’t really like soccer all that much. I decided to quit playing and just focus on my studies. I was pretty smart to begin with, so it wasn’t that hard to keep getting good grades.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “For better or worse, my only saving grace was that I could do reasonably well out in the world, I suppose. But there are still times when I feel regret. Whenever I see Hirata and Shibata practicing out on the field, I think it could have been me out there. Even though I didn’t even like it that much. Strange, huh?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What about you? What was your childhood like, Ishizaki?”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No reason.”<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So that’s why you’re so good at studying, huh?”<span class=\"pg\">p.184<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No doubts there,”<span class=\"pg\">p.185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ishizaki Daichi<\/b> Cleaning rebute; night “minute” refused; draws the childhood question that opens the thaw.<span class=\"pg\">p.171, 182–185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Defends Keisei’s cleaning; names him worst-case expulsion body in the dark warning.<span class=\"pg\">p.171, 182<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Named in the soccer-field regret — practicing while Hashimoto watches the could-have-been.<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shibata Sō<\/b> Same field named with Hirata.<span class=\"pg\">p.183<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Alienation story — smart kid who quit what he didn’t love; self-deprecating chuckle; keeps the sprain secret earlier (half 1).<span class=\"pg\">p.183–185<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Ayanokōji’s grade: right-distance glue, harder to read than Sakayanagi or Katsuragi.<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Withdraws with a sigh when Ishizaki refuses the helping hand.<span class=\"pg\">p.182<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p153-1\">← Before: Ch.6 half 1: the joke, the refusal, the carry<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p186-1\">→ After: Ch.7 half 1: the second 3.6 km and the Katsuragi past<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p186-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"yukimura-teruhiko totsuka-yahiko katsuragi-kouhei sakayanagi-arisu matoba-shinji hashimoto-masayoshi","q":"hashimoto masayoshi ch 7 half 1  the second 3 6 km and the katsuragi past dorm relay  morning dusting talk with yahiko   in that case  it looks like i gotta do the same thing  i m not too shabby when it comes to running long distances myself   don t carry that burden alone  yukimura   that sure doesn t sound like you  you ve become much more understanding in only a day   no problem  our group s ranking impacts my own plans  i d like for us to score at least one spot above the lowest rank  isn t that right  yahiko   i ve squared off against katsuragi many times on sakayanagi s orders  you probably resent me for that  but right now we re allies for real  please forget about the past   i had nothing to do with that  that was matoba s plan  matches ishizaki at 3 6 km  offers points so keisei does not carry the burden alone  squared off against katsuragi on sakayanagi s orders  asks yahiko to forget the past  matoba s rep setup named  the past offences yahiko still resents   hindered by classmates on sakayanagi s orders  the orders behind the katsuragi squares  named as who set katsuragi up as representative    i had nothing to do with that  public ally for real frame  keeps ranking self interest visible  wry smile while smacking yahiko  continues as the glue who kept the group from collapsing  pov open","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p186-1\"><h3><span class=\"ttl\">Ch.7 half 1: the second 3.6 km and the Katsuragi past<\/span><span class=\"meta\">Y1V8 · p.186–193<\/span><\/h3><p class=\"setup\">Dorm relay; morning dusting talk with Yahiko.<\/p><p class=\"with\">with <a href=\"yukimura-teruhiko.html\">Yukimura Teruhiko<\/a> · <a href=\"totsuka-yahiko.html\">Totsuka Yahiko<\/a> · <a href=\"katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"matoba-shinji.html\">Matoba Shinji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“In that case, it looks like I gotta do the same thing. I’m not too shabby when it comes to running long distances myself”<span class=\"pg\">p.188<\/span><\/li><li class=\"q spoken\">“Don’t carry that burden alone, Yukimura”<span class=\"pg\">p.189<\/span><\/li><li class=\"q spoken\">“That sure doesn’t sound like you. You’ve become much more understanding in only a day.”<span class=\"pg\">p.193<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “No problem. Our group’s ranking impacts my own plans. I’d like for us to score at least one spot above the lowest rank. Isn’t that right, Yahiko?”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve squared off against Katsuragi many times on Sakayanagi’s orders. You probably resent me for that, but right now we’re allies for real. Please forget about the past.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I had nothing to do with that. That was Matoba’s plan.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Matches Ishizaki at 3.6 km; offers points so Keisei does not carry the burden alone.<span class=\"pg\">p.188–189<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Squared off against Katsuragi on Sakayanagi’s orders; asks Yahiko to forget the past; Matoba’s rep setup named.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> The past offences Yahiko still resents — hindered by classmates on Sakayanagi’s orders.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> The orders behind the Katsuragi squares.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Matoba Shinji<\/b> Named as who set Katsuragi up as representative — “I had nothing to do with that.”<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Public ally-for-real frame; keeps ranking self-interest visible; wry smile while smacking Yahiko.<span class=\"pg\">p.188–193<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> Continues as the glue who kept the group from collapsing (POV open).<span class=\"pg\">p.172, 186<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p171-1\">← Before: Ch.6 half 2: keep cleaning, then the soccer story<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p203-1\">→ After: Ch.7 half 2: midnight with Ryuuen, then Nagumo<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p203-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"ryuuen-kakeru nagumo-miyabi sakayanagi-arisu horikita-manabu ayanokouji-kiyotaka kouenji-rokusuke hirata-yousuke yukimura-teruhiko sudou-ken hashimoto-masayoshi","q":"hashimoto masayoshi ch 7 half 2  midnight with ryuuen  then nagumo slips out of the top bunk  corridor meeting with ryuuen  interrupted by nagumo and manabu  shaken when ayanokoji s name is used   hey  ryuuen   i just wanted to chat  i mean  you stand out way too much in the cafeteria  dude  the only time i can talk to you is the middle of the night   yeah  i called you here because it s the last day  right now  everyone else is sound asleep   look  i m not good at talking about stuff in a roundabout way  so i want to hear a straight answer  did you really quit being the class leader   at the very least  i don t buy that ishizaki and the others worked you over   i see  well  albert s certainly a threat  i guess  but the ryuuen kakeru i know isn t the kind of guy to cower before an opponent  if anything  he s the sort of guy who s always thinking up counterattacks  isn t he   i see  so that s it   not sure  i m still fifty fifty  personally  i think i want you to fight back against the situation you re in   yep  i want the  promise of class a  just like you   if necessary   selling out sakayanagi doesn t come cheap  ryuuen  right now  she s at the top of our class  i m on the winning team  get it   i m pretty good at making my way in the world  you should know that i can come out on top pretty well  anyway  i m glad i could talk with you directly  doesn t look like you ve lost your fire   when you got overtaken by hirata s class  i wondered what the hell you were even doing  but they might be a tough bunch after all   kouenji is a threat  at the very least  to be honest  if he started acting to his class s advantage  there s no telling what would happen to class a  they also have academically gifted students like hirata and yukimura  and sudou  who s easily one of the most athletic students in our grade   anyway  there s no telling what will happen  but here s something to keep in mind  even if hirata s group does manage to make it all the way to class a  i m fine as long as there s room for me to slip in there too   it s shitty  but dragging this out is just a hassle   not sure  we re in different classes  so i can t really say   what do i  well  i think he s just a normal student   maybe because he performed well at the relay during the sports festival   no  midnight straight answer test on the leader quit  fifty fifty  class a promise alignment  caught in the corridor  used as the prop for the ayanokoji name play  visibly shaken   if necessary  dispose line   selling her out for the class a promise  third in the corridor triangle  stops when abstain is demanded  forced  normal student  answer when his name is emphasized  gaze on the top bunk after return  named top threat if he acts for his class  named academically gifted in the threat list  same threat list   easily one of the most athletic students in our grade  trails without flashlight  buys into twenty million class a  opportunism stated out loud  slip into class a even if hirata s group climbs   room for him is the condition","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p203-1\"><h3><span class=\"ttl\">Ch.7 half 2: midnight with Ryuuen, then Nagumo<\/span><span class=\"meta\">Y1V8 · p.203–211<\/span><\/h3><p class=\"setup\">Slips out of the top bunk; corridor meeting with Ryuuen; interrupted by Nagumo and Manabu; shaken when Ayanokōji’s name is used.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"kouenji-rokusuke.html\">Kōenji Rokusuke<\/a> <span class=\"n\">+3 more<\/span><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hey, Ryuuen,”<span class=\"pg\">p.204<\/span><\/li><li class=\"q spoken\">“I just wanted to chat. I mean, you stand out way too much in the cafeteria, dude. The only time I can talk to you is the middle of the night.”<span class=\"pg\">p.204<\/span><\/li><li class=\"q spoken\">“Yeah. I called you here because it’s the last day. Right now, everyone else is sound asleep.”<span class=\"pg\">p.204<\/span><\/li><\/ul><details class=\"more\"><summary>28 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Look, I’m not good at talking about stuff in a roundabout way. So I want to hear a straight answer. Did you really quit being the class leader?”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “At the very least, I don’t buy that Ishizaki and the others worked you over”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. Well, Albert’s certainly a threat, I guess. But the Ryuuen Kakeru I know isn’t the kind of guy to cower before an opponent. If anything, he’s the sort of guy who’s always thinking up counterattacks, isn’t he?”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I see. So that’s it.”<span class=\"pg\">p.204<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not sure. I’m still fifty-fifty. Personally, I think I want you to fight back against the situation you’re in.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yep. I want the ‘promise of Class A.’ Just like you.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If necessary.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Selling out Sakayanagi doesn’t come cheap, Ryuuen. Right now, she’s at the top of our class. I’m on the winning team. Get it?”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’m pretty good at making my way in the world. You should know that I can come out on top pretty well. Anyway, I’m glad I could talk with you directly. Doesn’t look like you’ve lost your fire.”<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “When you got overtaken by Hirata’s class, I wondered what the hell you were even doing. But they might be a tough bunch after all.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Kouenji is a threat, at the very least. To be honest, if he started acting to his class’s advantage, there’s no telling what would happen to Class A. They also have academically gifted students like Hirata and Yukimura, and Sudou, who’s easily one of the most athletic students in our grade.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Anyway, there’s no telling what will happen, but here’s something to keep in mind. Even if Hirata’s group does manage to make it all the way to Class A, I’m fine as long as there’s room for me to slip in there too.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It’s shitty, but dragging this out is just a hassle.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Not sure. We’re in different classes, so I can’t really say.”<span class=\"pg\">p.209<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do I…? Well, I think he’s just a normal student.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe because he performed well at the relay during the Sports Festival?”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No.”<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Midnight straight-answer test on the leader-quit; fifty-fifty; Class A promise alignment.<span class=\"pg\">p.203–207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> Caught in the corridor; used as the prop for the Ayanokōji-name play; visibly shaken.<span class=\"pg\">p.207–210<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> “If necessary” dispose line — selling her out for the Class A promise.<span class=\"pg\">p.205<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Third in the corridor triangle; stops when abstain is demanded.<span class=\"pg\">p.207–211<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Forced “normal student” answer when his name is emphasized; gaze on the top bunk after return.<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kōenji Rokusuke<\/b> Named top threat if he acts for his class.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Named academically gifted in the threat list.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yukimura Teruhiko<\/b> Same threat list.<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> “easily one of the most athletic students in our grade.”<span class=\"pg\">p.207<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Trails without flashlight; buys into twenty-million Class A; opportunism stated out loud.<span class=\"pg\">p.203–205<\/span><\/li><li><span class=\"mlabel\">Goal<\/span> Slip into Class A even if Hirata’s group climbs — room for him is the condition.<span class=\"pg\">p.205<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p186-1\">← Before: Ch.7 half 1: the second 3.6 km and the Katsuragi past<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p220-1\">→ After: Ch.9 half 1: the Ryuuen probe<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p220-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"ryuuen-kakeru ayanokouji-kiyotaka nagumo-miyabi hashimoto-masayoshi","q":"hashimoto masayoshi ch 9 half 1  the ryuuen probe beside ayanokoji after zazen  opens the ryuuen isolation read and steers toward nagumo s interest   well  no use worryin  about it  nothing ya can do now  right  ayanokouji   ishizaki and albert s eyes  i don t get the impression that they hate him  if anything  they look sorrowful  like pets whose master has abandoned them   that s what they say  but maybe there s something more to ryuuen stepping down  don t you think so   i see  sorry for asking you something weird  reads the isolation as more than a fallout  admits he has no evidence linking ayanokoji to ryuuen  almost certainly no evidence  still steers the talk because nagumo asked about ryuuen  the overnight interest still in his head  will not confront ayanokoji directly  smooth disengage once the probe is deflected","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p220-1\"><h3><span class=\"ttl\">Ch.9 half 1: the Ryuuen probe<\/span><span class=\"meta\">Y1V8 · p.220–221<\/span><\/h3><p class=\"setup\">Beside Ayanokōji after zazen; opens the Ryuuen-isolation read and steers toward Nagumo’s interest.<\/p><p class=\"with\">with <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"nagumo-miyabi.html\">Nagumo Miyabi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Well, no use worryin’ about it. Nothing ya can do now. Right, Ayanokouji?”<span class=\"pg\">p.220<\/span><\/li><li class=\"q spoken\">“Ishizaki and Albert’s eyes. I don’t get the impression that they hate him. If anything, they look sorrowful. Like pets whose master has abandoned them.”<span class=\"pg\">p.220<\/span><\/li><li class=\"q spoken\">“That’s what they say, but…maybe there’s something more to Ryuuen stepping down. Don’t you think so?”<span class=\"pg\">p.221<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I see. Sorry for asking you something weird.”<span class=\"pg\">p.221<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Reads the isolation as more than a fallout; admits he has no evidence linking Ayanokōji to Ryuuen.<span class=\"pg\">p.220–221<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Almost certainly no evidence; still steers the talk because Nagumo asked about Ryuuen.<span class=\"pg\">p.220–221<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nagumo Miyabi<\/b> The overnight interest still in his head; will not confront Ayanokōji directly.<span class=\"pg\">p.220–221<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Smooth disengage once the probe is deflected.<span class=\"pg\">p.220–221<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p203-1\">← Before: Ch.7 half 2: midnight with Ryuuen, then Nagumo<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p233-1\">→ After: Ch.9 half 2: the solidarity mechanics<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v8-p233-1","v":"y1v8","y":1,"o":10,"k":"spoken","w":"tachibana-akane ikari-momoko hashimoto-masayoshi","q":"hashimoto masayoshi ch 9 half 2  the solidarity mechanics states the trap in one breath when the girls  results land   tachibana senpai dragged down ikari senpai s group  he said   as a result  their group s score fell below the average  so she s being taken down as well via the solidary rule  that s all there is to it  isn t it  names her as the dragged down class a student  the representative whose group took the hit   solidary rule  kept as printed   translation for the solidarity rule","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v8-p233-1\"><h3><span class=\"ttl\">Ch.9 half 2: the solidarity mechanics<\/span><span class=\"meta\">Y1V8 · p.233<\/span><\/h3><p class=\"setup\">States the trap in one breath when the girls’ results land.<\/p><p class=\"with\">with <a href=\"tachibana-akane.html\">Tachibana Akane<\/a> · <a href=\"ikari-momoko.html\">Ikari Momoko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Tachibana-senpai dragged down Ikari-senpai’s group,” he said. “As a result, their group’s score fell below the average, so she’s being taken down as well via the solidary rule. That’s all there is to it, isn’t it?”<span class=\"pg\">p.233<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Tachibana Akane<\/b> Names her as the dragged-down Class A student.<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ikari Momoko<\/b> The representative whose group took the hit.<span class=\"pg\">p.233<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “solidary rule” kept as printed — translation for the solidarity rule.<span class=\"pg\">p.233<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v8-p220-1\">← Before: Ch.9 half 1: the Ryuuen probe<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v9-p43-1","v":"y1v9","y":1,"o":11,"k":"action spoken","w":"kanzaki-ryuuji ichinose-honami katsuragi-kouhei ryuuen-kakeru sakayanagi-arisu hashimoto-masayoshi","q":"hashimoto masayoshi gymnasium  accused of spreading the ichinose rumors gymnasium   hashimoto faces kanzaki with miyake between them and the ayanokoji group arriving  target of kanzaki s all day tail and questioning  eventually admits helping rumors along   you guys aren t really going to fight  are you    opening deflection when the group arrives  earlier   you re quite persistent  miyake   rumors  ah  you mean the ones about ichinose doing various malicious things  what connection do i have with those rumors   playing dumb is just a waste of everyone s time    kanzaki s charge  hashimoto answers evasively   you can t have smoke without a fire  that s probably what most students are thinking  presses that ichinose neither affirmed nor denied the rumors  quotes her reply to kanzaki  argues a good person now need not have been good in the past   she said something like   i hope you aren t entranced by any of those rumors  don t take them to heart  contempt for kanzaki s blind faith    oh give it up kanzaki  responses like that stink so much that i can t even look you in the eyes   then i ll tell you  i ve been spreading around rumors about ichinose    admits passing rumors along while denying origin   in other words  you have no intention of retracting those rumors    kanzaki s read  hashimoto says rumors cannot be taken back   these last few days  i ve been doing a thorough investigation on you guys in class a    kanzaki s counter  hashimoto floats ryuuen as alternative   maybe it s the handiwork of ryuuen and he s actually just pretending to have retired  named as the other class a figure who could order class a students  after sakayanagi  invokes ryuuen as a possible hidden hand to deflect kanzaki  denies instruction from sakayanagi while not denying class a involvement  ayanokoji s read  from how hashimoto speaks and acts  the rumors  aren t all lies  never names the original source  only admits helping pass rumors along","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v9-p43-1\"><h3><span class=\"ttl\">Gymnasium: accused of spreading the Ichinose rumors<\/span><span class=\"meta\">Y1V9 · p.43–50<\/span><\/h3><p class=\"setup\">Gymnasium — Hashimoto faces Kanzaki with Miyake between them and the Ayanokōji Group arriving.<\/p><p class=\"with\">with <a href=\"kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“You guys aren’t really going to fight, are you?” — opening deflection when the group arrives; earlier: “You’re quite persistent, Miyake.”<span class=\"pg\">p.43<\/span><\/li><li class=\"q spoken\">“Rumors? Ah, you mean the ones about Ichinose doing various malicious things? What connection do I have with those rumors?”<span class=\"pg\">p.45<\/span><\/li><li class=\"q spoken\">“Playing dumb is just a waste of everyone’s time.” — Kanzaki’s charge; Hashimoto answers evasively.<span class=\"pg\">p.45<\/span><\/li><\/ul><details class=\"more\"><summary>14 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Target of Kanzaki’s all-day tail and questioning; eventually admits helping rumors along.<span class=\"pg\">p.43–50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You can’t have smoke without a fire. That’s probably what most students are thinking.”<span class=\"pg\">p.46<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Presses that Ichinose neither affirmed nor denied the rumors; quotes her reply to Kanzaki; argues a good person now need not have been good in the past.<span class=\"pg\">p.47–50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “She said something like: ‘I hope you aren’t entranced by any of those rumors. Don’t take them to heart.’”<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Contempt for Kanzaki’s blind faith — “Oh give it up Kanzaki. Responses like that stink so much that I can’t even look you in the eyes.”<span class=\"pg\">p.47–48<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> “Then I’ll tell you. I’ve been spreading around rumors about Ichinose.” — admits passing rumors along while denying origin.<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In other words, you have no intention of retracting those rumors.” — Kanzaki’s read; Hashimoto says rumors cannot be taken back.<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “These last few days, I’ve been doing a thorough investigation on you guys in Class A.” — Kanzaki’s counter; Hashimoto floats Ryuuen as alternative.<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Maybe it’s the handiwork of Ryuuen and he’s actually just pretending to have retired?”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Named as the other Class A figure who could order Class A students, after Sakayanagi.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Invokes Ryuuen as a possible hidden hand to deflect Kanzaki.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Denies instruction from Sakayanagi while not denying Class A involvement.<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Limit<\/span> Ayanokōji’s read: from how Hashimoto speaks and acts, the rumors “aren’t all lies.”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Never names the original source; only admits helping pass rumors along.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v9-p51-1\">→ After: Leaving the gym; the dorm tail<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v9-p51-1","v":"y1v9","y":1,"o":11,"k":"action spoken","w":"kanzaki-ryuuji hasebe-haruka ayanokouji-kiyotaka hashimoto-masayoshi","q":"hashimoto masayoshi leaving the gym  the dorm tail gym dispersal   hashimoto pats kanzaki s shoulder on the way out   haven t we said enough  even if we continue the conversation  we won t end up being able to agree on anything anyway  gestures farewell to haruka and airi and leaves toward the school building  ends the standoff by walking away while the conversation is declared unfinished  farewell gesture  haruka and airi stay with the group  ayanokoji feels incongruity in how hashimoto treats him now  later camera confirms hashimoto is following him and has come to the cafe  never looks at or speaks to ayanokoji while passing  purpose of the tail not stated on these pages","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v9-p51-1\"><h3><span class=\"ttl\">Leaving the gym; the dorm tail<\/span><span class=\"meta\">Y1V9 · p.51, 53, 56<\/span><\/h3><p class=\"setup\">Gym dispersal — Hashimoto pats Kanzaki’s shoulder on the way out.<\/p><p class=\"with\">with <a href=\"kanzaki-ryuuji.html\">Kanzaki Ryūji<\/a> · <a href=\"hasebe-haruka.html\">Hasebe Haruka<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Haven’t we said enough? Even if we continue the conversation, we won’t end up being able to agree on anything anyway.”<span class=\"pg\">p.51<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> Gestures farewell to Haruka and Airi and leaves toward the school building.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kanzaki Ryūji<\/b> Ends the standoff by walking away while the conversation is declared unfinished.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hasebe Haruka<\/b> Farewell gesture; Haruka and Airi stay with the group.<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Ayanokōji feels incongruity in how Hashimoto treats him now; later camera-confirms Hashimoto is following him and has come to the cafe.<span class=\"pg\">p.51, 53, 56<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Never looks at or speaks to Ayanokōji while passing; purpose of the tail not stated on these pages.<span class=\"pg\">p.53, 56<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v9-p43-1\">← Before: Gymnasium: accused of spreading the Ichinose rumors<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v9-p81-1\">→ After: Named among possible rumor sources<\/button><\/div><\/article>"},{"i":"sc-hashimoto-masayoshi-y1v9-p81-1","v":"y1v9","y":1,"o":11,"k":"","w":"sakayanagi-arisu hashimoto-masayoshi","q":"hashimoto masayoshi named among possible rumor sources ayanokoji s narration  hashimoto may have acted alone or under second  or third year instructions   sakayanagi still ostensibly denies involvement  does not appear  named in the source elimination aside only","h":"<article class=\"card\" id=\"sc-hashimoto-masayoshi-y1v9-p81-1\"><h3><span class=\"ttl\">Named among possible rumor sources<\/span><span class=\"meta\">Y1V9 · p.81<\/span><\/h3><p class=\"with\">with <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Ayanokōji’s narration: Hashimoto may have acted alone or under second- or third-year instructions — Sakayanagi still ostensibly denies involvement.<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Does not appear; named in the source-elimination aside only.<span class=\"pg\">p.81<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hashimoto-masayoshi-y1v9-p51-1\">← Before: Leaving the gym; the dorm tail<\/button><\/div><\/article>"}];
